const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/estimating/catalogs/%7Bcatalog_id%7D/items',
  qs: {
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    type: 'SOME_ARRAY_VALUE',
    cost_item_unit: 'SOME_ARRAY_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/estimating/catalogs/%7Bcatalog_id%7D/items?page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&type=SOME_ARRAY_VALUE&cost_item_unit=SOME_ARRAY_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

